styles.h1:
font-family: "Caveat", "Ma Shan Zheng", cursive;
font-size: 28px;
line-height: 1.5;
position: relative;
color: #2c3e50;
margin-bottom: 8px;
letter-spacing: 1px;
font-weight: 600;
text-align: center;
padding-bottom: 5px;
border-bottom: 2px dashed #3498db;

styles.h2:
font-size: 16px;
color: #7f8c8d;
margin-bottom: 24px;
font-weight: 400;
letter-spacing: 0.5px;
text-align: center;
position: relative;
font-style: italic;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.p:
color: #34495e;
font-size: 15px;
line-height: 24px;
margin: 16px 0;
position: relative;
z-index: 1;

styles.strong:
font-weight: 600;
text-decoration: underline;
text-decoration-color: #e74c3c;
text-decoration-style: wavy;
text-underline-offset: 4px;

styles.a:
color: #3498db;
text-decoration: none;
border-bottom: 1px dashed #3498db;
transition: all 0.3s ease;

styles.li:
position: relative;


margin-bottom: 20px;
color: #34495e;
line-height: 24px;
font-size: 15px;

styles.blockquote:
background-color: #f8f9fa;
border-left: 4px solid #3498db;
color: #7f8c8d;
padding: 10px 20px;
margin: 20px 0;
font-style: italic;
position: relative;

styles.pre:
border: 1px solid #ecf0f1;
box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
background-color: #f8f9fa;
border-radius: 4px;
padding: 16px;
font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
font-size: 13px;
overflow-x: auto;

styles.hr:
border: 0;
height: 1px;
background: repeating-linear-gradient(
  90deg,
  transparent,
  transparent 5px,
  #3498db 5px,
  #3498db 10px
);
margin: 24px 0;

styles.img:
max-width: 100%;
border: 1px solid #ecf0f1;
border-radius: 4px;
box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
margin: 20px 0;
padding: 5px;
background: white;

styles.table:
box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
border-radius: 4px;
overflow: hidden;
margin: 20px 0;
border-collapse: collapse;

styles.th:
background-color: #f8f9fa;
color: #2c3e50;
border-bottom: 2px solid #3498db;
padding: 10px;
font-weight: 600;
